CREATE OR REPLACE FUNCTION public.preview_move_onboarding(p_source uuid,p_target uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $function$
DECLARE s public.personnel%ROWTYPE; t public.personnel%ROWTYPE; sj jsonb; tj jsonb; reasons jsonb:='[]'; fields jsonb:='[]'; counts jsonb:='{}'; source_history jsonb:='{}'; target_history jsonb:='{}'; f text; tab text; mode text; action text; note text; sv jsonb; tv jsonb; display_s jsonb; display_t jsonb; n bigint; tn bigint; skips bigint;
BEGIN
IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin'::public.app_role) THEN RAISE EXCEPTION 'Admin access required' USING ERRCODE='42501'; END IF;
FOREACH f IN ARRAY ARRAY['first_name','last_name','email','phone','date_of_birth','address','city','state','zip','photo_url','ssn_last_four','ssn_full','itin','citizenship_status','immigration_status','work_authorization_status','work_authorization_type','work_auth_expiry','id_document_url','i9_completed_at','everify_status','everify_case_number','everify_verified_at','everify_expiry','bank_name','bank_account_type','bank_routing_number','bank_account_number','direct_deposit_signed_at','direct_deposit_signature','tax_classification','tax_ein','tax_business_name','w9_signed_at','w9_signature','w9_certification','ica_signed_at','ica_signature','gender','sms_consent_at','sms_consent_version','photo_consent_at','photo_consent_version','background_consent_at','background_consent_version','email_verified_at','email_verified_source','phone_verified_at','phone_verified_source','hourly_rate','pay_rate','bill_rate','rating','vendor_id','linked_vendor_id','employer_customer_id','status','portal_required','non_billable','notes','onboarding_status','onboarding_completed_at','home_lat','home_lng','geocoded_at','geocode_source','is_geocodable','banking_info_updated_at','banking_info_updated_by','bank_account_number_encrypted','bank_routing_number_encrypted','bank_account_last4','merged_at','merged_by','merge_reason','user_id','id','personnel_number','deleted_at','merged_into_id'] LOOP
IF NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid='public.personnel'::regclass AND attname=f AND attnum>0 AND NOT attisdropped) THEN RAISE EXCEPTION 'Required personnel column missing: %',f; END IF; END LOOP;
SELECT * INTO s FROM public.personnel WHERE id=p_source; IF NOT FOUND THEN reasons:=reasons||jsonb_build_array('Source not found'); END IF;
SELECT * INTO t FROM public.personnel WHERE id=p_target; IF NOT FOUND THEN reasons:=reasons||jsonb_build_array('Target not found'); END IF;
IF s.id IS NULL OR t.id IS NULL THEN RETURN jsonb_build_object('eligible',false,'reasons',reasons,'fields',fields,'counts',counts); END IF;
IF s.id=t.id THEN reasons:=reasons||jsonb_build_array('Source and target must differ'); END IF;
IF s.merged_into_id IS NOT NULL OR t.merged_into_id IS NOT NULL THEN reasons:=reasons||jsonb_build_array('A record already has merged_into_id'); END IF;
IF s.deleted_at IS NOT NULL OR t.deleted_at IS NOT NULL THEN reasons:=reasons||jsonb_build_array('A record is deleted'); END IF;
IF NOT(coalesce(s.onboarding_status='completed',false) OR s.onboarding_completed_at IS NOT NULL) THEN reasons:=reasons||jsonb_build_array('Source onboarding is not completed'); END IF;
IF coalesce(t.onboarding_status='completed',false) OR t.onboarding_completed_at IS NOT NULL THEN reasons:=reasons||jsonb_build_array('Target onboarding is already completed'); END IF;
IF s.user_id IS NOT NULL AND t.user_id IS NOT NULL THEN reasons:=reasons||jsonb_build_array('Both records have portal logins'); END IF;
FOREACH tab IN ARRAY ARRAY['time_entries','location_attendance','personnel_project_assignments','location_assignments','site_checkin_tokens','visit_personnel','timesheet_signature_requests','personnel_payments','personnel_expenses','reimbursements','project_labor_expenses','shift_extensions','variance_resolutions','personnel_hotel_assignments','crew_members','punch_link_events'] LOOP
EXECUTE format('SELECT count(*) FROM public.%I WHERE personnel_id=$1',tab) INTO n USING s.id; EXECUTE format('SELECT count(*) FROM public.%I WHERE personnel_id=$1',tab) INTO tn USING t.id;
source_history:=source_history||jsonb_build_object(tab,n); target_history:=target_history||jsonb_build_object(tab,tn); IF n>0 THEN reasons:=reasons||jsonb_build_array('Source has '||n||' row(s) in '||tab); END IF; END LOOP;
IF (target_history->>'time_entries')::bigint=0 AND (target_history->>'location_attendance')::bigint=0 AND (target_history->>'visit_personnel')::bigint=0 THEN reasons:=reasons||jsonb_build_array('Target has no work history'); END IF;
FOREACH tab IN ARRAY ARRAY['personnel_documents','personnel_w9_forms','document_signatures','emergency_contacts','personnel_certifications','personnel_badges','personnel_languages','personnel_capabilities','personnel_engagement_notes','personnel_onboarding_tokens','personnel_registrations','onboarding_email_deliveries'] LOOP
EXECUTE format('SELECT count(*) FROM public.%I WHERE personnel_id=$1',tab) INTO n USING s.id; skips:=0;
CASE tab
WHEN 'personnel_w9_forms' THEN SELECT count(*) INTO skips FROM public.personnel_w9_forms a WHERE a.personnel_id=s.id AND EXISTS(SELECT 1 FROM public.personnel_w9_forms b WHERE b.personnel_id=t.id);
WHEN 'document_signatures' THEN SELECT count(*) INTO skips FROM public.document_signatures a WHERE a.personnel_id=s.id AND EXISTS(SELECT 1 FROM public.document_signatures b WHERE b.personnel_id=t.id AND b.document_id=a.document_id);
WHEN 'personnel_badges' THEN SELECT count(*) INTO skips FROM public.personnel_badges a WHERE a.personnel_id=s.id AND a.active AND EXISTS(SELECT 1 FROM public.personnel_badges b WHERE b.personnel_id=t.id AND b.active);
WHEN 'personnel_capabilities' THEN SELECT count(*) INTO skips FROM public.personnel_capabilities a WHERE a.personnel_id=s.id AND EXISTS(SELECT 1 FROM public.personnel_capabilities b WHERE b.personnel_id=t.id AND lower(b.capability)=lower(a.capability));
WHEN 'personnel_engagement_notes' THEN SELECT count(*) INTO skips FROM public.personnel_engagement_notes a WHERE a.personnel_id=s.id AND EXISTS(SELECT 1 FROM public.personnel_engagement_notes b WHERE b.personnel_id=t.id AND b.project_id=a.project_id AND coalesce(b.location_id,'00000000-0000-0000-0000-000000000000'::uuid)=coalesce(a.location_id,'00000000-0000-0000-0000-000000000000'::uuid));
ELSE NULL; END CASE;
counts:=counts||jsonb_build_object(tab,jsonb_build_object('source',n,'move',n-skips,'skip',skips)); END LOOP;
sj:=to_jsonb(s);tj:=to_jsonb(t);
FOREACH f IN ARRAY ARRAY['first_name','last_name','email','phone','date_of_birth','address','city','state','zip','photo_url','ssn_last_four','ssn_full','itin','citizenship_status','immigration_status','work_authorization_status','work_authorization_type','work_auth_expiry','id_document_url','i9_completed_at','everify_status','everify_case_number','everify_verified_at','everify_expiry','bank_name','bank_account_type','bank_routing_number','bank_account_number','direct_deposit_signed_at','direct_deposit_signature','tax_classification','tax_ein','tax_business_name','w9_signed_at','w9_signature','w9_certification','ica_signed_at','ica_signature','gender','sms_consent_at','sms_consent_version','photo_consent_at','photo_consent_version','background_consent_at','background_consent_version','email_verified_at','email_verified_source','phone_verified_at','phone_verified_source','hourly_rate','pay_rate','bill_rate','rating','vendor_id','linked_vendor_id','employer_customer_id','status','portal_required','non_billable','notes'] LOOP
mode:=CASE WHEN f=ANY(ARRAY['first_name','last_name','email','phone']) THEN 'contact' WHEN f=ANY(ARRAY['hourly_rate','pay_rate','bill_rate','rating','vendor_id','linked_vendor_id','employer_customer_id','status','portal_required','non_billable','notes']) THEN 'employment' ELSE 'profile' END;
sv:=sj->f;tv:=tj->f;note:=NULL;
IF f IN('bank_account_number','bank_routing_number') THEN
IF (sv IS NULL OR sv='null'::jsonb OR sv='""'::jsonb) AND sj->(f||'_encrypted') IS NOT NULL AND sj->(f||'_encrypted')<>'null'::jsonb THEN sv:='"Encrypted value present"'::jsonb; END IF;
IF (tv IS NULL OR tv='null'::jsonb OR tv='""'::jsonb) AND tj->(f||'_encrypted') IS NOT NULL AND tj->(f||'_encrypted')<>'null'::jsonb THEN tv:='"Encrypted value present"'::jsonb; END IF; END IF;
action:=CASE WHEN sv IS NULL OR sv='null'::jsonb OR sv='""'::jsonb THEN 'keep' WHEN mode='contact' THEN 'keep' WHEN tv IS NULL OR tv='null'::jsonb OR tv='""'::jsonb THEN 'fill' WHEN mode='employment' OR sv=tv THEN 'keep' ELSE 'conflict' END;
IF f IN('bank_account_number','bank_routing_number') AND (sv='"Encrypted value present"'::jsonb OR tv='"Encrypted value present"'::jsonb) AND sv IS NOT NULL AND sv<>'null'::jsonb AND sv<>'""'::jsonb AND tv IS NOT NULL AND tv<>'null'::jsonb AND tv<>'""'::jsonb THEN action:='conflict'; END IF;
IF f LIKE 'email_verified_%' AND public.normalize_email(s.email) IS DISTINCT FROM public.normalize_email(t.email) THEN action:='keep';note:='Verification follows chosen email, never a different address'; ELSIF f LIKE 'phone_verified_%' AND public.normalize_phone(s.phone) IS DISTINCT FROM public.normalize_phone(t.phone) THEN action:='keep';note:='Verification follows chosen phone, never a different number'; END IF;
display_s:=sv;display_t:=tv;
IF f IN('ssn_full','ssn_last_four','itin','tax_ein','bank_account_number') THEN
 display_s:=CASE WHEN sv IS NULL OR sv='null'::jsonb OR sv='""'::jsonb THEN 'null'::jsonb WHEN sv='"Encrypted value present"'::jsonb THEN CASE WHEN s.bank_account_last4 IS NULL THEN '"Present"'::jsonb ELSE to_jsonb('••••'||right(s.bank_account_last4,4)) END ELSE to_jsonb('••••'||right(sv#>>'{}',4)) END;
 display_t:=CASE WHEN tv IS NULL OR tv='null'::jsonb OR tv='""'::jsonb THEN 'null'::jsonb WHEN tv='"Encrypted value present"'::jsonb THEN CASE WHEN t.bank_account_last4 IS NULL THEN '"Present"'::jsonb ELSE to_jsonb('••••'||right(t.bank_account_last4,4)) END ELSE to_jsonb('••••'||right(tv#>>'{}',4)) END;
ELSIF f IN('bank_routing_number','direct_deposit_signature','w9_signature','ica_signature','photo_url','id_document_url') THEN display_s:=CASE WHEN sv IS NULL OR sv='null'::jsonb OR sv='""'::jsonb THEN 'null'::jsonb ELSE '"Present"'::jsonb END;display_t:=CASE WHEN tv IS NULL OR tv='null'::jsonb OR tv='""'::jsonb THEN 'null'::jsonb ELSE '"Present"'::jsonb END; END IF;
fields:=fields||jsonb_build_array(jsonb_build_object('field',f,'source',display_s,'target',display_t,'action',action,'mode',mode,'note',note)); END LOOP;
RETURN jsonb_build_object('eligible',jsonb_array_length(reasons)=0,'reasons',reasons,'fields',fields,'counts',counts,'source',jsonb_build_object('id',s.id,'personnel_number',s.personnel_number,'name',concat_ws(' ',s.first_name,s.last_name),'phone',s.phone,'ssn_last4',right(coalesce(nullif(s.ssn_last_four,''),s.ssn_full),4),'bank_last4',right(coalesce(nullif(s.bank_account_last4,''),s.bank_account_number),4)),'target',jsonb_build_object('id',t.id,'personnel_number',t.personnel_number,'name',concat_ws(' ',t.first_name,t.last_name),'phone',t.phone,'ssn_last4',right(coalesce(nullif(t.ssn_last_four,''),t.ssn_full),4),'bank_last4',right(coalesce(nullif(t.bank_account_last4,''),t.bank_account_number),4)),'source_history',source_history,'target_untouched',target_history,'portal_login_action',CASE WHEN s.user_id IS NOT NULL AND t.user_id IS NULL THEN 'move' ELSE 'keep' END);
END;$function$;
REVOKE ALL ON FUNCTION public.preview_move_onboarding(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.preview_move_onboarding(uuid,uuid) TO authenticated;